package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat._parseDate.
 * Since _parseDate is protected, we use a subclass to expose it for testing.
 */
public class StdDateFormat__parseDate_TriageGen0Test {

    private TestableStdDateFormat dateFormat;

    /**
     * Subclass to expose the protected method _parseDate.
     */
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        @Override
        public Date _parseDate(String dateStr, ParsePosition pos) throws java.text.ParseException {
            return super._parseDate(dateStr, pos);
        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParseISO8601() throws java.text.ParseException {
        // This triggers the looksLikeISO8601(dateStr) branch
        String isoDate = "2023-10-27T10:00:00Z";
        Date result = dateFormat._parseDate(isoDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseLongTimestamp() throws java.text.ParseException {
        // This triggers the branch where it checks if the string is a long timestamp
        // (i < 0 && NumberInput.inLongRange)
        String timestamp = "1698393600000";
        Date result = dateFormat._parseDate(timestamp, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseNegativeLongTimestamp() throws java.text.ParseException {
        // This triggers the branch: (dateStr.charAt(0) == '-')
        String negativeTimestamp = "-1698393600000";
        Date result = dateFormat._parseDate(negativeTimestamp, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseRFC1123() throws java.text.ParseException {
        // This triggers the fallback to parseAsRFC1123
        // It must not look like ISO8601 and must not be a pure number
        String rfcDate = "Fri, 27 Oct 2023 10:00:00 GMT";
        Date result = dateFormat._parseDate(rfcDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseRFC1123FallbackNull() throws java.text.ParseException {
        // This triggers the fallback to parseAsRFC1123 which returns null for invalid formats
        String invalidDate = "not-a-date";
        Date result = dateFormat._parseDate(invalidDate, new ParsePosition(0));
        assertNull(result);
    }

    @Test
    public void testParseBranchWithNonNumericChar() throws java.text.ParseException {
        // Tests the while loop logic: if (ch < '0' || ch > '9')
        // We provide a string that is not ISO8601 and not a long, but contains non-digits
        // to ensure the loop breaks correctly.
        String mix = "123abc456";
        // This should fail the long check and fall back to RFC1123, which returns null
        Date result = dateFormat._parseDate(mix, new ParsePosition(0));
        assertNull(result);
    }

    @Test
    public void testParseBranchWithNegativeSignNotAtStart() throws java.text.ParseException {
        // The logic: if (i > 0 || ch != '-') { break; }
        // This tests the specific condition regarding negative numbers in the loop
        String midNegative = "123-456";
        Date result = dateFormat._parseDate(midNegative, new ParsePosition(0));
        // Should fall back to RFC1123 and return null
        assertNull(result);
    }

    @Test
    public void testParseWithParsePositionOffset() throws java.text.ParseException {
        // Ensure ParsePosition is actually utilized
        String isoDate = "2023-10-27T10:00:00Z";
        ParsePosition pos = new ParsePosition(0);
        Date result = dateFormat._parseDate(isoDate, pos);
        assertNotNull(result);
        assertEquals(isoDate.length(), pos.getIndex());
    }
}
